set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from the test environment' > site/hello.txt
cat > test-env.conf <<'EOF'
# The test environment, checked in beside the tests: surl -K test-env.conf
# The passwords are for throwaway test accounts only.

directory = site
user = "tester:secret"              # logs in over HTTP and FTP
mail-domain = example.com
mailbox = "app@example.com:secret"  # the app's mailbox, over SMTP

# The tests log in over plain http:// and ftp://, and upload over FTP.
allow-plaintext-auth
allow-uploads

url = http://127.0.0.1:0/
url = ftp://127.0.0.1:0/
url = smtp://127.0.0.1:0/
EOF
dotnet run test-env-from-file.cs -- start
